    // predefined
    TransferData(e) {
      this.maps = [];
      this.options = {};
      this.center = [];
      this.flag = false;
      this.isShow = false;
      this.model.refresh();
      this.value = "On what day of the week?";
      this.badcase_distribution_param = null;
      this.TimeInfoProcessor.refresh();
      if (e == "violation_XM_ARIMA") {

        this.TimeInfoProcessor.updateParam(
          xm_hm["start_time"],
          xm_hm["end_time"],
          xm_hm["time_fitness"], 'min'
        );

        this.flag = true;
        this.isShow = true;
        this.TimeInfoProcessor.emitTimeSeries()
        setTimeout(() => {
          this.model.update(
            xm_hm["pred"],
            xm_hm["gt"],
            xm_hm["stationinfo"]
          );
        }, 400)

        setTimeout(() => {
          if (this.flag)
